#!/usr/bin/env node
import { mkdirSync, readdirSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseFrontmatter } from './lib/frontmatter.mjs';

const HEADER =
  '# GENERATED by scripts/gen-codex-agents.mjs from agents/{file}. Do not edit; run `npm run gen:codex`.\n';

// Single-line TOML basic string; JSON escapes are valid TOML escapes.
const str = JSON.stringify;

/** TOML multiline literal string, falling back to an escaped basic string when it cannot hold `body`. */
export function multiline(body) {
  const text = body.replace(/\r\n/g, '\n').trim();
  if (!text.includes("'''") && !text.endsWith("'")) return `'''\n${text}\n'''`;
  return `"""\n${text.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}\n"""`;
}

const SANDBOXES = ['read-only', 'workspace-write', 'inherit'];

// Optional `codex-sandbox` wins (`inherit` omits the key); else read-only when tools lack Write/Edit.
function sandboxMode(override, tools, file) {
  if (override === undefined) {
    return tools.includes('Write') || tools.includes('Edit') ? null : 'read-only';
  }
  if (!SANDBOXES.includes(override)) {
    throw new Error(`${file}: codex-sandbox must be one of ${SANDBOXES.join(', ')}`);
  }
  return override === 'inherit' ? null : override;
}

/** Render one agents/*.md file as Codex agent TOML. Throws when required fields are missing. */
export function renderAgent(text, file) {
  const parsed = parseFrontmatter(text);
  if (!parsed) throw new Error(`${file}: missing frontmatter`);
  const { data, body } = parsed;
  for (const key of ['name', 'description']) {
    if (!data[key]) throw new Error(`${file}: missing ${key}`);
  }
  const tools = (data.tools ?? 'Write').split(',').map((t) => t.trim());
  const lines = [HEADER.replace('{file}', file), `name = ${str(data.name)}`];
  lines.push(`description = ${str(data.description)}`);
  // Claude `effort: max` is Codex `xhigh` (same mapping as Codex's own migrator).
  if (data.effort) {
    lines.push(`model_reasoning_effort = ${str(data.effort === 'max' ? 'xhigh' : data.effort)}`);
  }
  const sandbox = sandboxMode(data['codex-sandbox'], tools, file);
  if (sandbox) lines.push(`sandbox_mode = ${str(sandbox)}`);
  lines.push(`developer_instructions = ${multiline(body)}`, '');
  return lines.join('\n');
}

/** Map of `<name>.toml` to expected content for every agents/*.md under root. */
export function generate(root) {
  const dir = join(root, 'agents');
  const out = new Map();
  for (const file of readdirSync(dir)
    .filter((f) => f.endsWith('.md'))
    .sort()) {
    const toml = renderAgent(readFileSync(join(dir, file), 'utf8'), file);
    out.set(file.replace(/\.md$/, '.toml'), toml);
  }
  return out;
}

function existing(outDir) {
  try {
    return readdirSync(outDir).filter((f) => f.endsWith('.toml'));
  } catch {
    return [];
  }
}

/** Files whose content differs, or that are missing or extra, in codex/agents. */
export function stale(root, expected = generate(root)) {
  const outDir = join(root, 'codex', 'agents');
  const present = existing(outDir);
  const problems = [];
  for (const [name, content] of expected) {
    if (!present.includes(name)) problems.push(`missing: codex/agents/${name}`);
    else if (readFileSync(join(outDir, name), 'utf8') !== content) {
      problems.push(`differs: codex/agents/${name}`);
    }
  }
  for (const name of present) if (!expected.has(name)) problems.push(`extra: codex/agents/${name}`);
  return problems;
}

/** Returns the process exit code. */
export function run({ argv, root, stdout, stderr }) {
  let expected;
  try {
    expected = generate(root);
  } catch (err) {
    stderr(`gen-codex-agents: ${err.message}\n`);
    return 1;
  }
  if (argv.includes('--check')) {
    const problems = stale(root, expected);
    if (problems.length === 0) return 0;
    stderr(`${problems.join('\n')}\nrun \`npm run gen:codex\` and commit the result\n`);
    return 1;
  }
  const outDir = join(root, 'codex', 'agents');
  mkdirSync(outDir, { recursive: true });
  for (const name of existing(outDir)) if (!expected.has(name)) rmSync(join(outDir, name));
  for (const [name, content] of expected) writeFileSync(join(outDir, name), content);
  stdout(`wrote ${expected.size} agent files to codex/agents\n`);
  return 0;
}

export function main(proc = process, metaUrl = import.meta.url) {
  proc.exitCode = run({
    argv: proc.argv.slice(2),
    root: join(dirname(fileURLToPath(metaUrl)), '..'),
    stdout: (s) => proc.stdout.write(s),
    stderr: (s) => proc.stderr.write(s),
  });
}

// realpath both sides: a symlinked plugin dir (stow, --plugin-dir) must still run main.
export function isEntry(argv1, metaUrl, real = realpathSync) {
  try {
    return real(argv1) === real(fileURLToPath(metaUrl));
  } catch {
    return false;
  }
}

if (isEntry(process.argv[1], import.meta.url)) main();
